 // (After the last step has settled.)\n      const lift = t + (j === 1 ? 0.1 : 0.18);\n      const land = lift + gap * 0.8;\n      let x = C[0] + nn[0] * g + Math.cos(f) * 0.05 * L;\n      let y = C[1] + nn[1] * g + Math.sin(f) * 0.05 * L;\n      const apart = Math.hypot(x - other.x, y - other.y);\n      if (apart < 0.7 * L) {\n        x += nn[0] * sideOf(k) * (0.7 * L - apart);\n        y += nn[1] * sideOf(k) * (0.7 * L - apart);\n      }\n      const was = w.feet[k][w.feet[k].length - 1];\n      const size = clamp(Math.hypot(x - was.x, y - was.y) / (2 * P.stepLen * L) + 0.12, 0.2, 0.45);\n      if (j === 1) addKey(w, { t: lift, ...toward(other), rest: true });\n      const s = addStep(w, k, x, y, f + sideOf(k) * w.toeOut * 1.4, land, gap * 0.8, size);\n      // The weight goes onto the foot just put down, so the other can lift next;\n      // after the last step it settles between the two.\n      const at = j < n ? toward({ x, y }) : { x: (x + other.x) / 2, y: (y + other.y) / 2 };\n      s.key = addKey(w, { t: land + 0.15, ...at, rest: true, step: true });\n      t = land;\n      k = 1 - k;\n    }\n    w.dir = to;\n    return t;\n  }\n\n  // Small idle step while standing: one foot re-settles into an easy stance next to\n  // the other (a little apart, turned out, perhaps a little ahead or behind).\n  function planShuffle(w) {\n    const k = w.load === sideOf(0) ? 1 : w.load === sideOf(1) ? 0 : Math.random() < 0.5 ? 0 : 1;\n    const f = w.feet[k][w.feet[k].length - 1];\n    const o = w.feet[1 - k][w.feet[1 - k].length - 1];\n    const face = w.facing;\n    const n = [-Math.sin(face), Math.cos(face)];\n    // Across from the other foot by an easy stance width, a little ahead or behind.\n    const width = rand(0.55, 0.85) * L * sideOf(k);\n    const ahead = rand(-0.3, 0.3) * L;\n    const x = o.x + n[0] * width + Math.cos(face) * ahead;\n    const y = o.y + n[1] * width + Math.sin(face) * ahead;\n    const lift = w.t + 0.05;\n    const land = lift + 0.32;\n    const C = pelvisAt(w, w.t);\n    addKey(w, { t: lift, x: C[0], y: C[1], rest: true });\n    w.stagger = false;\n    const size = clamp(Math.hypot(x - f.x, y - f.y) / (2 * P.stepLen * L) + 0.1, 0.15, 0.35);\n    const s = addStep(w, k, x, y, face + sideOf(k) * (w.standToe + rand(-0.1, 0.1)), land, 0.32, size);\n    s.key = addKey(w, { t: land + 0.3, x: (x + o.x) / 2, y: (y + o.y) / 2, rest: true, step: true });\n  }\n\n  function startWalking(w, after, turned) {\n    after = Math.max(after, lastStep(w).land + 0.05);\n    const C = pelvisAt(w, after);\n    const key = addKey(w, { t: after, x: C[0], y: C[1], rest: true });\n    // After a turn the foot that did not move last goes first; otherwise the foot\n    // behind (relative to where we are going).\n    const d = [Math.cos(w.dir), Math.sin(w.dir)];\n    const f0 = w.feet[0][w.feet[0].length - 1];\n    const f1 = w.feet[1][w.feet[1].length - 1];\n    const foot = turned ? 1 - lastStep(w).k : (f0.x - f1.x) * d[0] + (f0.y - f1.y) * d[1] < 0 ? 0 : 1;\n    // A moment's anticipation: weight onto the standing foot before the first lifts.\n    const lean = w.flee > 0 ? 0 : 0.3;\n    const stand = w.feet[1 - foot][w.feet[1 - foot].length - 1];\n    if (lean) addKey(w, { t: after + lean, x: lerp(C[0], stand.x, 0.15), y: lerp(C[1], stand.y, 0.15), rest: true });\n    w.start = { key: lean ? w.keys[w.keys.length - 1] : key, foot, t: after + lean };\n    w.mode = 'walk';\n    w.load = 0;\n    w.stagger = false;\n    // No second thoughts until the first steps are down.\n    w.watch = Math.max(w.watch, after + lean - w.t + 1);\n  }\n\n  // A walker mid-stride: the last two footprints already down, the rest planned.\n  function initWalking(w, x, y, since, kLast) {\n    const d = [Math.cos(w.dir), Math.sin(w.dir)];\n    const n = [-d[1], d[0]];\n    const period = P.stepT / w.cad;\n    const v = (P.stepLen * L * w.lenF) / period;\n    for (const [k, land] of [[1 - kLast, w.t - since - period], [kLast, w.t - since]]) {\n      const kt = land + P.stance / w.cad / 2;\n      const K = { x: x + d[0] * v * (kt - w.t), y: y + d[1] * v * (kt - w.t) };\n      const lead = P.plantLead * L;\n      const g = w.gap * L * sideOf(k);\n      const s = addStep(w, k, K.x + d[0] * lead + n[0] * g, K.y + d[1] * lead + n[1] * g, w.dir + sideOf(k) * w.toeOut, land, swingT() / w.cad, 1);\n      const sw = P.sway * L * sideOf(k);\n      s.key = addKey(w, { t: kt, x: K.x + n[0] * sw, y: K.y + n[1] * sw, cx: K.x, cy: K.y, step: true });\n    }\n    w.mode = 'walk';\n  }\n\n  function initStanding(w, x, y) {\n    const n = [-Math.sin(w.dir), Math.cos(w.dir)];\n    const ahead = rand(0.15, 0.35) * L * (Math.random() < 0.5 ? -0.5 : 0.5);\n    for (let k = 0; k < 2; k++) {\n      const g = w.gap * L * rand(0.8, 1.05) * sideOf(k);\n      const fx = x + n[0] * g + Math.cos(w.dir) * ahead * sideOf(k);\n      const fy = y + n[1] * g + Math.sin(w.dir) * ahead * sideOf(k);\n      const s = addStep(w, k, fx, fy, w.dir + sideOf(k) * (w.standToe + rand(-0.1, 0.1)), w.t - 1 - k * 0.3, 0.4, 0.3);\n      s.key = addKey(w, { t: s.land + 0.3, x, y, rest: true, step: true });\n    }\n    w.mode = 'stand';\n    w.standLeft = rand(1.5, 5);\n    w.idleIn = rand(1.5, 3.5);\n    w.loadIn = rand(0.2, 1);\n    // Having just stood, not straight into another stop.\n    w.willStop = Math.random() < 0.3;\n    w.stopIn = rand(3, 8);\n  }\n\n  // A point just outside the screen on a random edge (not the one given).\n  function edgePoint(not) {\n    const m = L * 3;\n    let e = Math.floor(rand(0, 4));\n    if (e === not) e = (e + 2) % 4;\n    const p = e === 0 ? { x: -m, y: rand(0, Host.h) } : e === 1 ? { x: Host.w + m, y: rand(0, Host.h) } : e === 2 ? { x: rand(0, Host.w), y: -m } : { x: rand(0, Host.w), y: Host.h + m };\n    p.edge = e;\n    return p;\n  }\n\n  // On a tall screen most people cross from side to side, a little slanted: walking\n  // toward or away from the vanishing point would stack legs, stride and body in one\n  // column, while crossing it opens the stride across the legs' lean.\n  function tall() {\n    return Host.h > 1.3 * Host.w;\n  }\n\n  function spawnPoint() {\n    if (!tall() || Math.random() > 0.72) return edgePoint(-1);\n    const e = Math.random() < 0.5 ? 0 : 1;\n    return { x: e === 0 ? -L * 3 : Host.w + L * 3, y: rand(0.15, 0.85) * Host.h, edge: e };\n  }\n\n  // Where to head from p: the far side when the screen is tall, else any other edge.\n  function goalFrom(p, edge) {\n    if (!tall() || Math.random() > 0.72) return edgePoint(edge);\n    const e = edge === 0 || edge === 1 ? 1 - edge : p.x < Host.w / 2 ? 1 : 0;\n    const y = clamp(p.y + rand(0.15, 0.5) * Host.h * (Math.random() < 0.5 ? -1 : 1), 0.05 * Host.h, 0.95 * Host.h);\n    return { x: e === 0 ? -L * 3 : Host.w + L * 3, y, edge: e };\n  }\n\n  function makeWalker(anywhere) {\n    const tag = TAGS[serial % TAGS.length];\n    const number = String((serial % 9) + 1).padStart(2, '0');\n    serial++;\n    const w = {\n      id: serial,\n      t: 0,\n      x: 0,\n      y: 0,\n      dir: 0,\n      facing: 0,\n      goal: null,\n      feet: [[], []],\n      keys: [],\n      off: [0, 0],\n      anchor: null,\n      start: null,\n      watch: 0,\n      sway: 0,\n      speed: 0,\n      relax: 0,\n      load: 0,\n      loadIn: 0,\n      mode: 'walk',\n      flee: 0,\n      startle: 0,\n      // Most passers-by pause somewhere in the middle of the screen, briefly.\n      willStop: Math.random() < 0.85,\n      stopIn: rand(0.2, 1.2),\n      stagger: false,\n      standLeft: 0,\n      idleIn: 0,\n      // Everybody walks a little differently.\n      cad: SOLO ? 1 : rand(0.87, 1.15),\n      lenF: 1,\n      gap: SOLO ? P.footGap : P.footGap * rand(0.88, 1.1),\n      toeOut: SOLO ? 0.06 : rand(0.03, 0.13),\n      standToe: rand(0.1, 0.2),\n      shoe: SOLO ? 'sneaker' : SHOE_MIX[Math.floor(rand(0, SHOE_MIX.length))],\n      shoeLen: SOLO ? 1 : rand(0.9, 1.05),\n      shoeWide: SOLO ? 1.04 : rand(0.98, 1.08),\n      seed: rand(0, 